body.code:
/* Spatial rhythm expressed as geometric proportions */
:root {
  --golden-ratio: 1.618;
  --monolith-void: calc(100vw / var(--golden-ratio));
}

/* Swiss modular grid baseline rhythm */
.editorial-stave {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: clamp(1rem, 2.5vw, 2.5rem);
}
